package org.sleepwell.app;
import android.app.*;import android.content.Intent;import android.os.Bundle;import android.os.Looper;import android.view.View;import android.widget.*;import java.time.*;import java.util.*;import org.json.*;
/** Private reviewed replacement of one recurring occurrence. Use edits a draft only. */
public final class NextAlarmOverrideActivity extends Activity {
 static final int REQUEST=847;private TripAlarmShift travel;private Alarm alarm;private String request,identity,error="",admission="",reviewZone;private LocalDate sourceDate,targetDate;private int minute;private long last;private NextAlarmOverride reviewed;private RecordCalendar calendar;private Dialog picker,details;private boolean resumed,retired,returning;private int renderEpoch,pickerEpoch;private View currentPage;
 static Intent edit(Activity owner,Alarm alarm,String request){return RecordUi.intent(owner,NextAlarmOverrideActivity.class).putExtra("alarm",alarm.json().toString()).putExtra("request",request);}
 @Override public void onCreate(Bundle state){super.onCreate(state);RecordUi.review(this);setResult(RESULT_CANCELED);try{request=getIntent().getStringExtra("request");if(!BackupRuntime.nonce(request))throw new IllegalArgumentException();alarm=Alarm.read(new JSONObject(getIntent().getStringExtra("alarm")));identity=AlarmRepeat.identity(alarm);String proposal=getIntent().getStringExtra(TripAlarmShift.EXTRA);if(proposal!=null)travel=TripAlarmShift.read(proposal);ZoneId zone=ZoneId.systemDefault();reviewZone=state==null?zone.getId():state.getString("zone");if(state!=null){sourceDate=LocalDate.parse(state.getString("source"));targetDate=LocalDate.parse(state.getString("target"));minute=state.getInt("minute");last=state.getLong("last");error=state.getString("error","");admission=state.getString("admission","");if(state.containsKey("reviewed"))reviewed=NextAlarmOverride.decode(new JSONObject(state.getString("reviewed")));}else{targetDate=LocalDate.now(zone);minute=alarm.hour*60+alarm.minute;sourceDate=targetDate;try{NextAlarmOverrides.saved(this,alarm);long source=NextAlarmOverrides.source(this,alarm,System.currentTimeMillis(),zone);sourceDate=Instant.ofEpochMilli(source).atZone(zone).toLocalDate();last=Prefs.of(this).getLong("lastOccurrence_"+alarm.id,0);if(alarm.nextOverride!=null){NextAlarmOverrides.current(this,alarm,zone);targetDate=alarm.nextOverride.targetDate;minute=alarm.nextOverride.hour*60+alarm.nextOverride.minute;last=alarm.nextOverride.last;}else{targetDate=sourceDate;minute=Instant.ofEpochMilli(source).atZone(zone).getHour()*60+Instant.ofEpochMilli(source).atZone(zone).getMinute();}}catch(RuntimeException invalid){admission=message(invalid);}}if(travel!=null)try{travel.check(this,alarm);if(state==null){NextAlarmOverride proposed=travel.value(alarm);sourceDate=proposed.sourceDate;targetDate=proposed.targetDate;minute=proposed.hour*60+proposed.minute;last=proposed.last;admission="";}}catch(RuntimeException changed){admission=message(changed);}if(minute<0||minute>=1440||last<0)throw new IllegalArgumentException();if(android.os.Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::cancel);render();if(state!=null&&state.containsKey("calendar"))openDate(state.getBundle("calendar"));else if(state!=null&&state.containsKey("picker")){openTime();if(picker instanceof SleepPicker.StateDialog)picker.onRestoreInstanceState(state.getBundle("picker"));}}catch(Exception invalid){finish();}}
 private static String message(Exception problem){return problem.getMessage()==null?"This occurrence needs review. Return to the alarm and reopen its next time.":problem.getMessage();}
 private NextAlarmOverride candidate(){if(travel!=null)travel.check(this,alarm);ZoneId zone=ZoneId.systemDefault();if(!zone.getId().equals(reviewZone))throw new IllegalArgumentException("The phone time zone changed. Cancel and reopen Next alarm only.");LocalDate today=LocalDate.now(zone);if(targetDate.isBefore(today)||targetDate.isAfter(today.plusDays(366)))throw new IllegalArgumentException("Choose a future target within the next 366 days.");if(sourceDate.isAfter(today.plusDays(366)))throw new IllegalArgumentException("The next source is over a year away. Review it closer to its date.");NextAlarmOverrides.saved(this,alarm);Alarm copy=Alarm.read(alarm.json());AlarmSkips.consumeSkip(copy);NextAlarmOverride value=new NextAlarmOverride(reviewed==null?UUID.randomUUID().toString():reviewed.nonce,NextAlarmOverride.baseKey(copy),sourceDate,targetDate,minute/60,minute%60,last,reviewZone);copy.setNextOverride(value);NextAlarmOverrides.draft(this,copy,alarm);if(travel!=null&&(value.at(zone)!=travel.target||value.sourceAt(copy,zone)!=travel.source||value.last!=travel.last))throw new IllegalArgumentException("The draft no longer matches the selected travel occurrence.");if(value.at(zone)<=System.currentTimeMillis())throw new IllegalArgumentException("The selected target has passed. Review a future date and time.");return value;}
 private boolean liveOwner(){return Looper.myLooper()==Looper.getMainLooper()&&resumed&&!retired&&!returning&&!isDestroyed()&&!isFinishing()&&!isChangingConfigurations();}
 private boolean currentRender(View page,int epoch){return liveOwner()&&epoch==renderEpoch&&page!=null&&page==currentPage&&page.isAttachedToWindow()&&page.getRootView()==getWindow().getDecorView();}
 private boolean interactive(){return currentRender(currentPage,renderEpoch)&&hasWindowFocus();}
 private Runnable action(View page,Runnable work){int epoch=renderEpoch;return ()->{if(currentRender(page,epoch)&&hasWindowFocus())work.run();};}
 private void cancel(){if(!interactive())return;returning=true;finish();}
 private void render(){
  if(retired||returning||isDestroyed()||isFinishing())return;renderEpoch++;
  LinearLayout body=Design.page(this,false,null,n->{});currentPage=body;RecordUi.label(this,body);RecordUi.menuAction(RecordUi.header(body,travel==null?"Next alarm only":"Apply travel shift once",action(body,this::cancel)),"Next alarm options",action(body,this::about),false);Design.space(body,14);
  Design.text(body,"Change one occurrence. Your regular schedule resumes afterward.",14,400,Design.MUTED);if(travel!=null){Design.space(body,10);Design.text(body,"Then returns to recurrence",15,600,Design.INK);Design.space(body,5);Design.text(body,"This is the selected saved travel wake time. Keep current alarm changes nothing. Use next time edits this alarm draft; Save alarm confirms it. Then the regular recurrence resumes.",14,500,Design.INK);}Design.space(body,16);
  if(admission.isEmpty()){
   Design.item(body,"calendar","Replacement date",targetDate.toString(),travel==null?action(body,()->openDate(null)):null);Design.line(body);Design.item(body,"clock","Replacement time",Design.clock(this,minute),travel==null?action(body,this::openTime):null);Design.line(body);
   Design.space(body,8);Design.text(body,"Time zone · "+reviewZone,12,400,Design.MUTED);Design.space(body,14);Design.button(body,"Review next time",false,action(body,this::review));
   if(reviewed!=null){
    ZoneId zone=ZoneId.of(reviewed.reviewZone);LinearLayout card=Design.col(this);Design.pad(card,18,18);card.setBackground(Design.shape(this,Design.SOFT,18));Design.text(card,"Reviewed change",13,500,Design.MUTED);Design.space(card,6);Design.text(card,Design.clock(this,reviewed.hour*60+reviewed.minute),40,600,Design.BROWN);Design.text(card,reviewed.targetDate.toString()+" · "+reviewed.reviewZone,15,500,Design.INK);Design.space(card,14);
    try{Alarm base=Alarm.read(alarm.json());base.setNextOverride(null);AlarmSkips.consumeSkip(base);long source=reviewed.sourceAt(base,zone),following=base.nextOrdinary(source,zone);Design.text(card,"Replaces "+RecordUi.clock(this,source,zone)+" on "+reviewed.sourceDate,13,400,Design.MUTED);Design.space(card,6);Design.text(card,following>0?"Following alarm · "+RecordUi.date(following,zone)+" · "+RecordUi.clock(this,following,zone):"No following ordinary occurrence",13,400,Design.MUTED);}
    catch(RuntimeException invalid){Design.text(card,"Review this occurrence again before using it.",13,500,Design.BROWN);}body.addView(card);
   }
  }else Design.text(body,admission,15,500,Design.BROWN);
  LinearLayout footer=RecordUi.footer(body);if(!error.isEmpty()){TextView issue=Design.text(footer,error,13,500,NightDialTokens.NEGATIVE);issue.setContentDescription("Next alarm review error");issue.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);Design.space(footer,8);}
  Design.text(footer,"Save alarm applies this change.",12,400,Design.MUTED);Design.space(footer,6);
  if(admission.isEmpty()){NextAlarmOverride displayed=reviewed;Button use=Design.button(footer,"Use next time",true,action(body,()->use(displayed)));RecordUi.enabled(use,reviewed!=null);}
  if(travel==null&&(alarm.nextOverride!=null||alarm.nextOverrideInvalid))Design.button(footer,"Undo next-time override",false,action(body,this::undo));
  Design.button(footer,travel==null?"Cancel":"Keep current alarm",false,action(body,this::cancel));
 }
 private void about(){if(!interactive())return;if(details!=null)details.dismiss();details=SleepPicker.message(this,"Changing the next alarm","Your recurring time, weekdays and repeat rule stay saved. After the changed occurrence, the regular schedule resumes.\n\nChoose a future, unambiguous local time before the following ordinary occurrence. Calendar adjustments do not move this explicit target; smart wake-up keeps its saved window. Travelling uses the phone’s current time zone. Missing or repeated daylight-saving times need review.\n\nUndo restores the regular future schedule and clears this occurrence’s skip. Use or Undo changes the draft only; Save alarm applies it. Cancel keeps the saved alarm unchanged.");}
 private void review(){if(!interactive())return;try{reviewed=candidate();error="";}catch(Exception invalid){reviewed=null;error=message(invalid);}render();}
 private void use(NextAlarmOverride displayed){if(!interactive()||displayed==null||reviewed!=displayed)return;try{NextAlarmOverride fresh=candidate();if(!fresh.key().equals(displayed.key()))throw new IllegalArgumentException("The reviewed time changed. Review it again.");Intent result=new Intent().putExtra("request",request).putExtra("draft",identity).putExtra("nextOverride",NextAlarmOverride.encode(displayed).toString());returning=true;setResult(RESULT_OK,result);finish();}catch(Exception invalid){error=message(invalid);reviewed=null;render();}}
 private void undo(){if(!interactive())return;returning=true;setResult(RESULT_OK,new Intent().putExtra("request",request).putExtra("draft",identity).putExtra("undo",true));finish();}
 private void openDate(Bundle restored){if(retired||returning||isDestroyed()||isFinishing()||travel!=null||!admission.isEmpty())return;int epoch=renderEpoch,request=++pickerEpoch;View page=currentPage;if(calendar!=null)calendar.close();calendar=new RecordCalendar(this,"Next alarm date",targetDate,restored,date->{if(!currentRender(page,epoch)||request!=pickerEpoch)return;targetDate=date;reviewed=null;error="";render();},null);}
 private void openTime(){if(retired||returning||isDestroyed()||isFinishing()||travel!=null||!admission.isEmpty())return;int epoch=renderEpoch,request=++pickerEpoch;View page=currentPage;if(picker!=null)picker.dismiss();picker=SleepPicker.time(this,"Next alarm time",minute,value->{if(!currentRender(page,epoch)||request!=pickerEpoch)return;minute=value;reviewed=null;error="";render();});}
 @Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putString("zone",reviewZone);state.putString("source",sourceDate.toString());state.putString("target",targetDate.toString());state.putInt("minute",minute);state.putLong("last",last);state.putString("error",error);state.putString("admission",admission);if(reviewed!=null)try{state.putString("reviewed",NextAlarmOverride.encode(reviewed).toString());}catch(JSONException impossible){throw new IllegalStateException(impossible);}if(calendar!=null&&calendar.showing())state.putBundle("calendar",calendar.state());if(picker instanceof SleepPicker.StateDialog&&picker.isShowing())state.putBundle("picker",picker.onSaveInstanceState());}
 @Override protected void onResume(){super.onResume();resumed=true;}
 @Override protected void onPause(){resumed=false;super.onPause();}
 @Override protected void onDestroy(){retired=true;resumed=false;renderEpoch++;pickerEpoch++;currentPage=null;if(calendar!=null)calendar.close();if(picker!=null)picker.dismiss();if(details!=null)details.dismiss();super.onDestroy();}
 @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);}
}
